package com.streamcraft.core.runtime;
import java.io.IOException; import java.util.*; import org.apache.flink.api.connector.source.*;
final class InfluxDbSourceEnumerator implements SplitEnumerator<InfluxDbSourceSplit,InfluxDbSourceEnumeratorState>{
 private final SplitEnumeratorContext<InfluxDbSourceSplit> context; private final ArrayDeque<InfluxDbSourceSplit> pending=new ArrayDeque<>(); private final Set<Integer> failedReaders=new TreeSet<>(); private final boolean bounded; private final Set<Integer> signaled=new HashSet<>();
 private final Map<String,Integer> splitOwners=new HashMap<>();
 InfluxDbSourceEnumerator(SplitEnumeratorContext<InfluxDbSourceSplit> c,InfluxDbSourceEnumeratorState s,com.streamcraft.shared.influxdb.InfluxDbSourceConfig cfg){context=c;bounded=cfg.readMode()==com.streamcraft.shared.influxdb.InfluxDbSourceConfig.ReadMode.FULL||cfg.maxPolls()>0;if(s!=null)pending.addAll(s.pendingSplits());int owner=0;for(InfluxDbSourceSplit split:pending)splitOwners.put(split.splitId(),owner++%Math.max(1,context.currentParallelism()));}
 public void start(){assign();} public void handleSplitRequest(int id,String h){assign();} public void addReader(int id){failedReaders.remove(id);signaled.remove(id);assign();}
 public void addSplitsBack(List<InfluxDbSourceSplit> s,int id){failedReaders.add(id);if(s!=null)s.stream().sorted(Comparator.comparing(InfluxDbSourceSplit::splitId)).forEach(split->{splitOwners.put(split.splitId(),-1);pending.addLast(split);});assign();}
 public InfluxDbSourceEnumeratorState snapshotState(long id){return new InfluxDbSourceEnumeratorState(new ArrayList<>(pending));} public void close()throws IOException{}
 private void assign(){if(pending.isEmpty()){signal();return;}Map<Integer,?> readers=context.registeredReaders().entrySet().stream().filter(e->!failedReaders.contains(e.getKey())&&!signaled.contains(e.getKey())).collect(java.util.stream.Collectors.toMap(Map.Entry::getKey,Map.Entry::getValue));if(readers.isEmpty())return;Map<Integer,List<InfluxDbSourceSplit>> a=new LinkedHashMap<>();int count=pending.size();for(int i=0;i<count;i++){InfluxDbSourceSplit s=pending.removeFirst();int t=splitOwners.getOrDefault(s.splitId(),0);if(t<0)t=readers.keySet().stream().min(Integer::compareTo).orElseThrow();if(readers.containsKey(t))a.computeIfAbsent(t,k->new ArrayList<>()).add(s);else pending.addLast(s);}if(!a.isEmpty())context.assignSplits(new SplitsAssignment<>(a));signal();}
 private void signal(){if(!bounded||!pending.isEmpty())return;context.registeredReaders().keySet().stream().sorted().filter(id->!failedReaders.contains(id)).filter(signaled::add).forEach(context::signalNoMoreSplits);}
}
